INSERT INTO alert_template_locales(template_id,locale,title,body) VALUES
  ('717fcd73-0ba1-52ea-9575-4c9c0134dfec','vi','Báo cháy khẩn cấp','Phát hiện cháy tại {{zone}}, tầng {{floor}}, tòa {{building}}. Di chuyển ngay theo lối thoát hiểm gần nhất, không dùng thang máy. Làm theo hướng dẫn của đội PCCC cơ sở.'),
  ('717fcd73-0ba1-52ea-9575-4c9c0134dfec','en','Fire emergency','Fire detected in {{zone}}, floor {{floor}}, building {{building}}. Evacuate immediately via the nearest exit; do not use elevators. Follow the instructions of the fire wardens.'),
  ('8ba9b163-b776-576b-a770-797d96d7f6e4','vi','Diễn tập PCCC','Đây là diễn tập PCCC tại {{zone}}, tầng {{floor}}, tòa {{building}}. Thực hiện quy trình sơ tán theo kế hoạch diễn tập, không hoảng loạn. Xác nhận đã nhận thông báo trên thiết bị.'),
  ('8ba9b163-b776-576b-a770-797d96d7f6e4','en','Fire drill','This is a fire drill in {{zone}}, floor {{floor}}, building {{building}}. Follow the planned evacuation procedure calmly. Acknowledge receipt of this notification on your device.');
INSERT INTO demo_scenarios(id,scenario_key,label,enabled,definition_json) VALUES
  ('364e4adc-21de-575c-9286-ee87590f23bb','FIRE_DRILL','Fire drill - AEGIS Tower A',1,'{"scenarioKey":"FIRE_DRILL","simulation":true,"buildingCode":"A","templateCode":"DRILL","locales":["vi","en"],"steps":[{"step":1,"action":"OPEN_INCIDENT","kind":"DRILL","openedBy":"secops"},{"step":2,"action":"PUBLISH_ALERT","templateCode":"DRILL","scope":{"buildingCode":"A"},"requestedBy":"secops"},{"step":3,"action":"AWAIT_DEVICE_ACKS","expectedDevices":480,"timeoutSeconds":300},{"step":4,"action":"RESOLVE_INCIDENT","closedBy":"secops"}],"notes":"Training only - not a real emergency broadcast system."}');
